import{z as o,x as i,o as A,c as m,q as t,j as r,D as B,d as e,s,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"权重许可条款细读","description":"","frontmatter":{"title":"权重许可条款细读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-weight-license-terms.md","filePath":"llm/eco-weight-license-terms.md","lastUpdated":1791063341000}'),d={name:"llm/eco-weight-license-terms.md"};function D(p,E,C,T,F,c){const l=i("Mermaid");return A(),m("div",null,[E[2]||(E[2]=t('<h1 id="权重许可条款细读" tabindex="-1">权重许可条款细读 <a class="header-anchor" href="#权重许可条款细读" aria-label="Permalink to &quot;权重许可条款细读&quot;">​</a></h1><div class="epigraph"><p>许可读的是「授予了什么、限制了什么、并入了什么、何时终止」，FAQ 读的是营销；两者长得像，法律效力完全不同。</p><footer>—— 据 Llama 社区许可、Gemma 使用条款、Apache 2.0 与 MIT 许可文本的结构整理</footer></div><p><a href="/llm/eco-license-spectrum">上一课</a>把许可画成四档谱系、五条轴，那是对外发言用的地图。落到你手上的一份权重，还得把条款文本本身读一遍：自有社区条款里的义务藏在长句里，宽松许可也不是没有条件。本课给一个通用的五段读法，拿 Llama 社区许可、Gemma 条款与 Apache 2.0 当解剖标本。后课处理衍生与合并时，要反复回到这几段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工程师读许可最常见的失败是只读摘要页。摘要会告诉你「可以商用」，但不会告诉你：衍生模型要怎么命名、多大规模要回来谈、使用政策是不是条款的一部分、违约时许可是否自动终止。这些恰恰是下游决策要用的部分。另一类失败是拿宽松许可的直觉去读自有条款——以为「权重公开 = 随便用」，结果在命名义务或政策并入处违约。缺口不是法律知识，而是一张固定的检查清单，让任何一份权重许可都能被系统地拆开。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>五段读法，顺序固定。第一段<strong>授予</strong>：许可给了什么权利——使用、复制、分发、再许可，是否区分研究与商用。第二段<strong>条件</strong>：行使权利要付出什么——保留版权与许可声明（MIT 的全部义务几乎都在这）、Apache 2.0 的 NOTICE 文件与修改声明。第三段<strong>限制</strong>：哪些事明确不给做——Llama 社区许可的月活门槛、衍生模型以 Llama 开头的命名要求，Gemma 条款对部分用途的排除。第四段<strong>并入</strong>：可接受使用政策是否「视为本许可的一部分」——并入意味着违反政策就是违约，而不是道德劝告。第五段<strong>终止</strong>：什么行为触发自动终止，终止后已分发副本的命运。读完五段，写成一张合规清单进仓库，而不是留在某个人脑子里。<span class="marginnote">「并入」是合同术语，意思是「把另一份文件当作本合同的一部分」。一旦使用政策并入许可，那份政策就从「官网上的倡议」升级成「合同条文」——违反它不再是「不文明使用」，而是违约。所以读自有社区条款时，第四段是优先级最高的一句：先确认政策有没有被并进来，再谈别的自由。</span></p>',7)),(A(),r(n,null,{default:B(()=>[s(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E5%AE%98%E6%96%B9%E8%AE%B8%E5%8F%AF%E6%96%87%E6%9C%AC%22%5D%20--%3E%20G%5B%22%E6%8E%88%E4%BA%88%EF%BC%9A%E7%BB%99%E4%BA%86%E4%BB%80%E4%B9%88%E6%9D%83%E5%88%A9%22%5D%0A%20%20TXT%20--%3E%20C%5B%22%E6%9D%A1%E4%BB%B6%EF%BC%9A%E8%A6%81%E4%BF%9D%E7%95%99%E4%BB%80%E4%B9%88%E3%80%81%E9%99%84%E4%BB%80%E4%B9%88%E5%A3%B0%E6%98%8E%22%5D%0A%20%20TXT%20--%3E%20R%5B%22%E9%99%90%E5%88%B6%EF%BC%9A%E6%9C%88%E6%B4%BB%E9%97%A8%E6%A7%9B%E4%B8%8E%E5%91%BD%E5%90%8D%E4%B9%89%E5%8A%A1%22%5D%0A%20%20TXT%20--%3E%20AUP%5B%22%E5%B9%B6%E5%85%A5%EF%BC%9A%E4%BD%BF%E7%94%A8%E6%94%BF%E7%AD%96%E6%98%AF%E5%90%A6%E5%8D%B3%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20TXT%20--%3E%20T%5B%22%E7%BB%88%E6%AD%A2%EF%BC%9A%E4%BD%95%E6%97%B6%E8%87%AA%E5%8A%A8%E5%A4%B1%E6%95%88%22%5D%0A%20%20G%20--%3E%20CL%5B%22%E5%90%88%E8%A7%84%E6%B8%85%E5%8D%95%E8%BF%9B%E4%BB%93%E5%BA%93%22%5D%0A%20%20C%20--%3E%20CL%0A%20%20R%20--%3E%20CL%0A%20%20AUP%20--%3E%20CL%0A%20%20T%20--%3E%20CL%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"并入条款是自有社区许可与宽松许可最大的结构差异。Apache 2.0 与 MIT 不约束你拿模型去做什么：法律只管作品，不管用途。Llama 社区许可与 Gemma 条款把使用政策并进合同后，「用模型做政策禁止的事」从伦理问题变成违约问题，责任可能沿发布链传递。这就是上一课说的「附加政策」轴在文本层的落点。第二层机制是商标与著作权的分工：命名要求（衍生命名以 Llama 开头、随附出处说明）保护的其实是品牌，不是作品本身——违反它不等于「盗版」，但照样违约。把这两层分开，你才知道自己冒的是什么风险。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"宽松许可也有条件：Apache 2.0 要求分发时保留 NOTICE 并注明你改过文件；MIT 要求保留版权与许可声明。它们不是「没条款」，只是条款短到容易被忽略。")],-1)),E[6]||(E[6]=a("p",null,"同一种「用途违规」，在两类许可下的后果完全不同：",-1)),(A(),r(n,null,{default:B(()=>[s(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E4%B8%8B%E6%B8%B8%E7%94%A8%E6%A8%A1%E5%9E%8B%E5%81%9A%E4%BA%86%E6%94%BF%E7%AD%96%E7%A6%81%E6%AD%A2%E7%9A%84%E4%BA%8B%22%5D%20--%3E%20Q%7B%22%E4%BD%BF%E7%94%A8%E6%94%BF%E7%AD%96%E5%B9%B6%E5%85%A5%E6%9D%A1%E6%AC%BE%E4%BA%86%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%E5%AE%BD%E6%9D%BE%E8%AE%B8%E5%8F%AF%EF%BC%9AApache%20%2F%20MIT%7C%20ETH%5B%22%E6%B3%95%E5%BE%8B%E4%B8%8D%E7%AE%A1%E7%94%A8%E9%80%94%EF%BC%9A%E4%BC%A6%E7%90%86%E4%B8%8E%E5%85%AC%E5%85%B3%E9%97%AE%E9%A2%98%22%5D%0A%20%20Q%20--%3E%7C%E7%A4%BE%E5%8C%BA%E6%9D%A1%E6%AC%BE%EF%BC%9ALlama%20%2F%20Gemma%7C%20BRK%5B%22%E8%BF%9D%E5%8F%8D%E5%B9%B6%E5%85%A5%E6%94%BF%E7%AD%96%E5%8D%B3%E8%BF%9D%E7%BA%A6%EF%BC%9A%E8%AE%B8%E5%8F%AF%E5%8F%AF%E7%BB%88%E6%AD%A2%22%5D%0A%20%20BRK%20--%3E%20LOSS%5B%22%E5%B7%B2%E9%83%A8%E7%BD%B2%E4%BA%A7%E7%BA%BF%E9%9D%A2%E4%B8%B4%E5%81%9C%E7%94%A8%E4%B8%8E%E5%90%88%E8%A7%84%E8%BF%BD%E8%B4%A3%22%5D%0A%20%20ETH%20--%3E%20REP%5B%22%E5%A3%B0%E8%AA%89%E9%A3%8E%E9%99%A9%E4%B8%BA%E4%B8%BB%EF%BC%8C%E8%AE%B8%E5%8F%AF%E5%B9%B6%E4%B8%8D%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">初学者容易把「衍生模型没按 Llama 开头命名」当成小事，或者反过来当成盗版。两种理解都不对：命名义务是商标层的品牌保护，违反它不构成著作权侵权，但构成违约——发布方可以据此终止许可，你的权重使用权整个悬空。把著作权义务与商标义务分开记账，才知道自己冒的是哪种风险。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是工程读法，不是法律意见：具体交易、跨境部署、与专利和商标的交叉，交给专业审查。条款文本随版本漂移，同一族模型的许可会在大版本间改写，读的必须是你下载那一刻附带的文本——这也是第五段要留意「以哪个版本为准」的原因。下载动作在很多条款里即视为接受，团队先把权重拉下来再补合规审查，顺序本身就是风险。<span class="marginnote">为什么顺序要倒过来？多数条款写明「下载或使用即视为接受全部条款」——权重落地的瞬间合同已生效，命名、规模、政策义务全都绑上了团队。事后审查才发现接不住时，撤也不是、留也不是。合规清单要赶在点击下载之前完成，这是整件事里最便宜的一道保险。</span>最后，五段读法只处理许可文本；模型卡上另写的自愿性使用指引不是条款，违反它不违约，但会被<a href="/llm/model-cards">模型卡</a>的读者当成承诺对照。后课的衍生与合并，每一步都要回到这张清单打勾。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五段读法：授予、条件、限制、并入、终止；读完落成仓库里的合规清单。</li><li>并入使用政策是自有条款与宽松许可的最大结构差异：用途从伦理问题变成违约问题。</li><li>命名与出处义务是商标层控制，与著作权限制分开理解。</li><li>宽松许可仍有条件：NOTICE、修改声明、保留版权声明，短不等于没有。</li><li>以下载那一刻的文本为准；下载即接受，合规审查要赶在拉权重之前。</li><li>出处：Llama 社区许可、Gemma 使用条款、Apache License 2.0、MIT 许可官方文本，按本课程整理。</li></ul>',5))])}const f=o(d,[["render",D]]);export{u as __pageData,f as default};
